418:     particles.forEach(particle => {
419:       particle.vy += particle.gravity * dt;
420:       particle.x += particle.vx * dt;
421:       particle.y += particle.vy * dt;
422:       particle.life -= dt;
423:     });
424:     particles = particles.filter(particle => particle.life > 0);
425:     floaters.forEach(floater => {
426:       floater.y -= dt * 38;
427:       floater.life -= dt;
428:     });
429:     floaters = floaters.filter(floater => floater.life > 0);
