455:   function update(dt) {
456:     if (dt > 0.05) {
457:       const steps = Math.ceil(dt / 0.05);
458:       for (let index = 0; index < steps; index += 1) update(dt / steps);
459:       return;
460:     }
461: 
462:     let speed = 0;
463:     if (state === 'playing') {
464:       speed = gameSpeed();
465:       scenery += dt * speed;
466:       elapsed += dt;
467:       if (Math.max(0, Math.ceil(DURATION - elapsed + bonusTime)) !== displayedTime) updateHud();
468:       invulnerable = Math.max(0, invulnerable - dt);
469:       shield = Math.max(0, shield - dt);
470: 
471:       const direction = Number(held.right) - Number(held.left);
472:       player.x = Math.max(28, Math.min(W - player.width - 28, player.x + direction * 360 * dt));
473:       player.leg += dt * (direction ? 18 : 10);
474:       player.vy += 1900 * dt;
475:       player.y += player.vy * dt;
476:       if (player.y >= ground - player.height) {
477:         player.y = ground - player.height;
478:         player.vy = 0;
479:         player.onGround = true;
480:       }
481: 
482:       dustTimer -= dt;
483:       if (player.onGround && direction && dustTimer <= 0) {
484:         dustTimer = 0.1;
485:         particles.push({
486:           x: player.x + (direction > 0 ? 5 : player.width - 5),
487:           y: ground - 3,
488:           vx: -speed * 0.18 + (Math.random() - 0.5) * 30,
489:           vy: -20 - Math.random() * 35,
490:           life: 0.3,
491:           max: 0.3,
492:           size: 2 + Math.random() * 3,
493:           gravity: 120,
494:           color: '#777668',
495:         });
496:       }
497: 
498:       spawnObstacle -= dt;
499:       if (spawnObstacle <= 0) {
500:         const tall = Math.random() > 0.48;
501:         obstacles.push({
502:           x: W + 22,
503:           y: ground - (tall ? 51 : 38),
504:           width: tall ? 43 : 54,
505:           height: tall ? 51 : 38,
506:           tall,
507:         });
508:         spawnObstacle = Math.max(0.68, 1.38 - elapsed * 0.009) + Math.random() * 0.34;
509:       }
510: 
511:       spawnPatch -= dt;
512:       if (spawnPatch <= 0) {
513:         spawnPatchGroup();
514:         spawnPatch = 1.05 + Math.random() * 0.62;
515:       }
516: 
517:       spawnPower -= dt;
518:       if (spawnPower <= 0) {
519:         const kind = Math.random() < 0.56 ? 'shield' : 'clock';
520:         powerups.push({ x: W + 26, y: ground - 132, width: 32, height: 32, kind, bob: Math.random() * Math.PI * 2 });
521:         spawnPower = 10.5 + Math.random() * 6;
522:       }
523: 
524:       const drift = speed * dt;
525:       obstacles.forEach(obstacle => { obstacle.x -= drift; });
526:       patches.forEach(patch => {
527:         patch.x -= drift;
528:         patch.spin += dt * 3;
529:       });
530:       powerups.forEach(powerup => {
531:         powerup.x -= drift;
532:         powerup.bob += dt * 4;
533:       });
534:       obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > -10);
535:       patches = patches.filter(patch => patch.x + patch.width > -10);
536:       powerups = powerups.filter(powerup => powerup.x + powerup.width > -10);
537: 
538:       const body = { x: player.x + 6, y: player.y + 5, width: player.width - 12, height: player.height - 7 };
539:       if (invulnerable <= 0) {
540:         const hit = obstacles.find(obstacle => overlaps(body, obstacle));
541:         if (hit) {
542:           obstacles = obstacles.filter(obstacle => obstacle !== hit);
543:           const centerX = hit.x + hit.width / 2;
544:           const centerY = hit.y + hit.height / 2;
545:           if (shield > 0) {
546:             shield = 0;
547:             invulnerable = 0.9;
548:             shake = Math.max(shake, 0.35);
549:             addBurst(centerX, centerY, ['#8fe6f2', '#f2f0e9'], 20, 210);
550:             addFloater('ESCUDO!', player.x + 12, player.y - 6, '#8fe6f2', 11);
551:             sfx.shieldBreak();
552:             updateHud();
553:             setStatus('O escudo absorveu a batida.');
554:           } else {
555:             lives -= 1;
556:             combo = 0;
557:             invulnerable = 1.35;
558:             shake = 0.75;
559:             flash = 0.75;
560:             addBurst(centerX, centerY, ['#e44d32', '#f2f0e9', '#b8422f'], 24, 230);
561:             addFloater('-1 VIDA', player.x + 4, player.y - 8, '#e44d32', 11);
562:             sfx.hit();
563:             updateHud();
564:             setStatus(`Batida! ${lives} ${lives === 1 ? 'vida restante' : 'vidas restantes'}.`);
565:             if (lives <= 0) {
566:               finishGame(false, 'lives');
567:               return;
568:             }
569:           }
570:         }
571:       }
572: 
573:       patches = patches.filter(patch => {
574:         const pickupBox = { x: body.x - 4, y: body.y - 5, width: body.width + 8, height: body.height + 10 };
575:         if (!overlaps(pickupBox, patch)) return true;
576:         score += 1;
577:         combo += 1;
578:         bestCombo = Math.max(bestCombo, combo);
579:         addBurst(patch.x + patch.width / 2, patch.y + patch.height / 2, ['#d6e363', '#f2f0e9'], 14, 170);
580:         addFloater('+1', patch.x + 6, patch.y - 2, '#d6e363', 12);
581:         if (combo > 0 && combo % 4 === 0) {
582:           bonusTime += 2;
583:           addFloater('COMBO +2s', player.x - 12, player.y - 20, '#f2f0e9', 10);
584:           sfx.combo();
585:         } else {
586:           sfx.pickup();
587:         }
588:         updateHud();
589:         setStatus(`Patch ${score} de ${TARGET}.`);
590:         if (score >= TARGET) finishGame(true, 'target');
591:         return false;
592:       });
593:       if (state !== 'playing') return;
594: 
595:       powerups = powerups.filter(powerup => {
596:         const pickupBox = { x: body.x - 8, y: body.y - 8, width: body.width + 16, height: body.height + 16 };
597:         if (!overlaps(pickupBox, powerup)) return true;
598:         if (powerup.kind === 'shield') {
599:           shield = 12;
600:           addFloater('ESCUDO 12s', powerup.x - 8, powerup.y - 2, '#8fe6f2', 11);
601:           setStatus('Escudo ativo por 12 segundos.');
602:         } else {
603:           bonusTime += 8;
604:           addFloater('+8 SEG', powerup.x - 4, powerup.y - 2, '#f2f0e9', 12);
605:           setStatus('Mais 8 segundos no relógio.');
606:         }
607:         addBurst(powerup.x + powerup.width / 2, powerup.y + powerup.height / 2, powerup.kind === 'shield' ? ['#8fe6f2', '#d6e363'] : ['#f2f0e9', '#e44d32'], 20, 190);
608:         sfx.power();
609:         updateHud();
610:         return false;
611:       });
612: 
613:       if (DURATION - elapsed + bonusTime <= 0) {
614:         finishGame(false, 'time');
615:         return;
616:       }
617:     } else if (state === 'ready') {
618:       scenery += dt * 40;
619:       player.leg += dt * 3;
620:     }
621: 
622:     updateEffects(dt);
623:   }
