625:   function drawSkyline(layer, factor, fill, windows) {
626:     const span = 1200;
627:     const shift = (scenery * factor) % span;
628:     layer.forEach((building, index) => {
629:       let x = building.x - shift;
630:       if (x + building.width < 0) x += span;
631:       if (x > W) return;
632:       ctx.fillStyle = fill;
633:       ctx.fillRect(x, ground - building.height, building.width, building.height);
634:       ctx.fillStyle = windows;
635:       const rows = Math.max(0, Math.floor(building.height / 25));
636:       for (let row = 0; row < rows; row += 1) {
637:         for (let column = 0; column < 3; column += 1) {
638:           if ((index + row + column) % 4 !== 0) {
639:             ctx.fillRect(x + 8 + column * 13, ground - building.height + 12 + row * 22, 4, 7);
640:           }
641:         }
642:       }
643:       if (index % 4 === 0) {
644:         ctx.fillStyle = fill;
645:         ctx.fillRect(x + building.width * 0.22, ground - building.height - 8, building.width * 0.2, 8);
646:       }
647:     });
648:   }
