    changed = true;
  }
  if (!Array.isArray(db.orders)) {
    db.orders = [];
    changed = true;
  }
  db.orders.forEach(order => {
    if (order.discount === undefined) {
      order.discount = 0;
      changed = true;
    }
    if (order.coupon === undefined) {
      order.coupon = null;
      changed = true;
    }
  });
  if (changed) localStorage.setItem(DB_KEY, JSON.stringify(db));
  return db;
}

function persist() {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
  window.dispatchEvent(new CustomEvent('rua98:data'));
}

