await page.fill('#checkout-coupon', 'RUA10');
await page.locator('.coupon-apply').click();
await page.waitForTimeout(300);
results.couponApplied = await page.locator('.coupon-hint').innerText();
results.discountLine = await page.locator('.checkout-discount').innerText();
results.checkoutTotalAfter = await page.locator('.checkout-total b').innerText();

// invalid coupon
