import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:8124/index.html?debug', { waitUntil: 'load' });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(400);
const results = {};
results.count = await page.locator('.favorites-count').innerText();
await page.locator('.favorite-btn').first().click();
await page.waitForTimeout(300);
results.countAfterFav = await page.locator('.favorites-count').innerText();
await page.locator('.favorites-toggle').click();
await page.waitForTimeout(600);
results.filteredCards = await page.locator('.product-card').count();
results.ariaPressed = await page.locator('.favorites-toggle').getAttribute('aria-pressed');
results.resultsText = await page.locator('.results-count').innerText();
results.overflow = await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
await page.locator('.clear-search').click().catch(() => {});
await page.waitForTimeout(200);
results.afterClear = await page.locator('.product-card').count();
results.errors = errors;
console.log(JSON.stringify(results, null, 2));
await page.screenshot({ path: 'screenshots/store-mobile-header.jpg', type: 'jpeg', quality: 68 });
await browser.close();

