71:   function filteredProducts() {
72:     const collections = new Map(RUA98.collections({ includeInactive: true }).map(collection => [collection.id, collection.name]));
73:     const term = state.search.trim().toLowerCase();
74:     const results = activeProducts().filter(product => {
75:       const matchesCategory = state.category === 'todos' || product.category === state.category;
76:       const matchesCollection = state.collection === 'todos' || product.collectionId === state.collection;
77:       const matchesFavorite = !state.favoritesOnly || RUA98.isFavorite(product.id);
78:       const haystack = [product.name, product.subtitle, product.tag, product.description, collections.get(product.collectionId) || '']
79:         .join(' ').toLowerCase();
80:       return matchesCategory && matchesCollection && matchesFavorite && (!term || haystack.includes(term));
81:     });
82:     if (state.sort === 'price-asc') results.sort((a, b) => a.price - b.price);
83:     else if (state.sort === 'price-desc') results.sort((a, b) => b.price - a.price);
84:     else if (state.sort === 'name') results.sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
85:     else if (state.sort === 'new') results.sort((a, b) => Number(b.isNew) - Number(a.isNew) || String(b.createdAt).localeCompare(String(a.createdAt)));
86:     else results.sort((a, b) => Number(b.featured) - Number(a.featured) || Number(b.isNew) - Number(a.isNew));
87:     return results;
88:   }
