  const type = input.type === 'fixed' ? 'fixed' : 'percent';
  if (type === 'percent' && value > 90) throw new Error('Desconto percentual máximo é 90%.');
  const coupons = db.settings.coupons || (db.settings.coupons = []);
  const original = input.originalCode ? String(input.originalCode).toUpperCase() : null;
  const existing = original ? coupons.find(c => c.code === original) : null;
  if (!existing && coupons.some(c => c.code === code)) throw new Error('Já existe um cupom com este código.');
  if (existing && code !== original && coupons.some(c => c.code === code)) throw new Error('Já existe um cupom com este código.');
  const coupon = {
