.favorites-toggle.active { color: var(--red); }
.favorites-toggle.active svg { fill: var(--red); stroke: var(--red); }
.header-actions { gap: 17px; }

@media (max-width: 700px) {
  .header-actions { gap: 11px; }
  .favorites-toggle .favorites-count { right: -7px; }
}

@media (max-width: 380px) {
  .header-actions { gap: 8px; }
}

