import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, acceptDownloads: true });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

const out = {};

// ---------- index: recent, hash, search ----------
await page.goto('http://localhost:8124/index.html?debug', { waitUntil: 'load' });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(500);
out.stockFlags = await page.locator('.stock-flag').count();
out.recentHiddenInitially = await page.locator('#recentes').evaluate(el => el.hidden);
await page.locator('[data-details="p1"]').click();
await page.waitForTimeout(450);
out.hashOpened = await page.evaluate(() => location.hash);
out.recentHiddenAfter = await page.locator('#recentes').evaluate(el => el.hidden);
out.recentCards = await page.locator('.recent-card').count();
out.shareButton = await page.locator('[data-detail-share]').count();
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
out.hashAfterClose = await page.evaluate(() => location.hash);
out.modalClosed = await page.locator('.product-modal').evaluate(el => !el.classList.contains('open'));

// deep link opens modal
await page.goto('http://localhost:8124/index.html?debug#produto=p2', { waitUntil: 'load' });
await page.waitForTimeout(700);
out.deepLinkTitle = await page.locator('#product-detail-title').innerText();
await page.locator('.product-close').click();
await page.waitForTimeout(250);

// search chips & shortcut
await page.keyboard.press('/');
await page.waitForTimeout(250);
out.searchOpenBySlash = await page.locator('.search-panel').evaluate(el => el.classList.contains('open'));
await page.locator('[data-search-term="preta"]').click();
await page.waitForTimeout(500);
out.searchValue = await page.locator('#search-input').inputValue();
out.searchResults = await page.locator('.product-card').count();
out.searchHint = await page.locator('#search-hint').innerText();
await page.locator('.clear-search').click().catch(async () => { await page.fill('#search-input', ''); });
await page.waitForTimeout(300);

// cart deep link
await page.evaluate(async () => { await RUA98.ready(); RUA98.addToCart('p1', 'M'); });
await page.goto('http://localhost:8124/index.html?cart=1#colecao', { waitUntil: 'load' });
await page.waitForTimeout(700);
out.cartDeepLinkOpen = await page.locator('body').evaluate(el => el.classList.contains('cart-open'));
out.urlCleaned = await page.evaluate(() => location.search);
await page.locator('.close-drawer').click();
await page.waitForTimeout(250);

// ---------- account: tracking, cancel, reorder ----------
await page.evaluate(async () => { await RUA98.ready(); await RUA98.login('cliente@rua98.com', 'rua123'); });
await page.goto('http://localhost:8124/conta.html#pedidos', { waitUntil: 'load' });
await page.waitForTimeout(700);
out.accountOrders = await page.locator('.account-order').count();
out.tracking = await page.locator('.order-tracking b').first().innerText();
out.reorderButtons = await page.locator('[data-reorder]').count();
out.cancelButtons = await page.locator('[data-cancel-order]').count();

// cancel the pending order (#1040 pago? order o1040 is pago) -> find one
const cancelBefore = await page.evaluate(() => RUA98.myOrders().find(o => ['pendente','pago'].includes(o.status))?.number || null);
out.cancelBefore = cancelBefore;
const target = page.locator('[data-cancel-order]').first();
await target.click();
out.cancelFirstLabel = await target.innerText();
await target.click();
await page.waitForTimeout(500);
out.cancelled = await page.evaluate(() => RUA98.myOrders().filter(o => o.status === 'cancelado').length);
out.cancelToast = await page.locator('.toast').innerText();

// reorder using the delivered order
const reorder = page.locator('[data-reorder]').first();
await reorder.click();
await page.waitForTimeout(1400);
out.reorderUrl = page.url();
out.reorderCartOpen = await page.locator('body').evaluate(el => el.classList.contains('cart-open')).catch(() => null);
out.reorderCartCount = await page.locator('.cart-count').innerText().catch(() => null);

// ---------- admin: coupons, tracking, CSV ----------
await page.evaluate(async () => { await RUA98.ready(); RUA98.logout(); });
await page.goto('http://localhost:8124/admin.html', { waitUntil: 'load' });
await page.fill('#admin-login-form input[name="email"]', 'admin@rua98.com');
await page.fill('#admin-login-form input[name="password"]', 'rua98admin');
await page.locator('#admin-login-form button[type="submit"]').click();
await page.waitForTimeout(800);
await page.locator('[data-panel="settings"]').click();
await page.waitForTimeout(500);
out.couponRows = await page.locator('.coupon-item').count();

// create coupon
await page.fill('#coupon-form input[name="code"]', 'RUA20');
await page.selectOption('#coupon-form select[name="type"]', 'percent');
await page.fill('#coupon-form input[name="value"]', '20');
await page.fill('#coupon-form input[name="minSubtotal"]', '200');
await page.fill('#coupon-form input[name="label"]', '20% OFF ACIMA DE 200');
await page.locator('#coupon-form button[type="submit"]').click();
await page.waitForTimeout(500);
out.couponCreated = await page.evaluate(() => RUA98.coupons({ includeInactive: true }).some(c => c.code === 'RUA20'));
out.couponRowsAfter = await page.locator('.coupon-item').count();

// edit it
const row = page.locator('.coupon-item', { hasText: 'RUA20' });
await row.locator('[data-action="edit-coupon"]').click();
await page.waitForTimeout(300);
out.editFilled = await page.locator('#coupon-form input[name="code"]').inputValue();
await page.fill('#coupon-form input[name="value"]', '25');
await page.locator('#coupon-form button[type="submit"]').click();
await page.waitForTimeout(400);
out.couponEdited = await page.evaluate(() => RUA98.coupons({ includeInactive: true }).find(c => c.code === 'RUA20').value);

// toggle
const row2 = page.locator('.coupon-item', { hasText: 'RUA20' });
await row2.locator('[data-action="toggle-coupon"]').click();
await page.waitForTimeout(400);
out.couponPaused = await page.evaluate(() => RUA98.coupons({ includeInactive: true }).find(c => c.code === 'RUA20').active);
await page.locator('.coupon-item', { hasText: 'RUA20' }).locator('[data-action="toggle-coupon"]').click();
await page.waitForTimeout(300);

// delete with confirm
await page.locator('.coupon-item', { hasText: 'RUA20' }).locator('[data-action="delete-coupon"]').click();
await page.waitForTimeout(300);
await page.locator('#confirm-yes').click();
await page.waitForTimeout(400);
out.couponDeleted = await page.evaluate(() => !RUA98.coupons({ includeInactive: true }).some(c => c.code === 'RUA20'));

// CSV exports
const downloadPromise = page.waitForEvent('download');
await page.locator('[data-panel="orders"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="export-orders"]').click();
const download = await downloadPromise;
out.ordersCsvName = download.suggestedFilename();
const path = await download.path();
out.ordersCsvOk = Boolean(path);

await page.locator('[data-action="export-customers"]').click().catch(() => {});
await page.locator('[data-panel="settings"]').click();
await page.waitForTimeout(300);
const newsDownload = page.waitForEvent('download');
await page.locator('[data-action="export-newsletter"]').click();
const nd = await newsDownload;
out.newsletterCsvName = nd.suggestedFilename();

// tracking edit on order
await page.locator('[data-panel="orders"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="view-order"]').first().click();
await page.waitForTimeout(400);
await page.fill('#tracking-form input[name="tracking"]', 'BR98 1234 5678');
await page.locator('#tracking-form button[type="submit"]').click();
await page.waitForTimeout(400);
out.trackingSaved = await page.evaluate(() => RUA98.orders().some(o => o.trackingCode === 'BR98 1234 5678'));
out.trackingInline = await page.locator('.tracking-inline').innerText();
await page.locator('[data-close-modal]').first().click();

out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

